/// What a notice says, one variant per notice code in the catalog.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub enum Announcement {
    /// `notice.default.chosen`: nothing decided `{decision}`, so it is {value}
    #[serde(rename = "notice.default.chosen")]
    NoticeDefaultChosen {
        /// The decision code it is about.
        decision: AnyCode,
        /// The value taken, in the decision code's words.
        value: String,
    },
    /// `heading.anchor.generated`: a heading has no letters or digits, so its anchor is `{anchor}`
    #[serde(rename = "heading.anchor.generated")]
    HeadingAnchorGenerated {
        /// The anchor given to the heading.
        anchor: String,
    },
    /// `footnote.name.generated`: the footnote `{given}` has no letters or digits, so its name is `{name}`
    #[serde(rename = "footnote.name.generated")]
    FootnoteNameGenerated {
        /// The name given instead.
        name: String,
        /// The name as the author wrote it.
        given: String,
    },
    /// `footnote.name.taken`: another footnote already has the name of `{given}`, so its name is `{name}`
    #[serde(rename = "footnote.name.taken")]
    FootnoteNameTaken {
        /// The name given instead.
        name: String,
        /// The name as the author wrote it.
        given: String,
    },
    /// `callout.kind.unknown`: the callout kind `{kind}` has no name a theme can use, so it is shown as a note
    #[serde(rename = "callout.kind.unknown")]
    CalloutKindUnknown {
        /// The kind, as written.
        kind: String,
    },
    /// `callout.metadata.ignored`: the callout metadata `{written}` styles a callout in Obsidian's own stylesheets, so it is not kept
    #[serde(rename = "callout.metadata.ignored")]
    CalloutMetadataIgnored {
        /// The text, as written.
        written: String,
    },
    /// `embed.inline.linked`: `{written}` is embedded where only text fits (a heading, a table cell, a link's text), so it is shown as a link
    #[serde(rename = "embed.inline.linked")]
    EmbedInlineLinked {
        /// The text, as written.
        written: String,
    },
    /// `embed.size.ignored`: the size `{written}` of an embedded image is not kept: the theme sizes images
    #[serde(rename = "embed.size.ignored")]
    EmbedSizeIgnored {
        /// The text, as written.
        written: String,
    },
    /// `embed.file.linked`: `{written}` is neither an image nor a note, so it is linked rather than embedded
    #[serde(rename = "embed.file.linked")]
    EmbedFileLinked {
        /// The text, as written.
        written: String,
    },
    /// `embed.footnote.dropped`: the footnotes of the page `{written}` embeds are not carried into this page, so their references are removed
    #[serde(rename = "embed.footnote.dropped")]
    EmbedFootnoteDropped {
        /// The text, as written.
        written: String,
    },
    /// `link.target.attached`: `{written}` could be any of {candidates}, so it is taken as `{target}`, the one in the vault's attachment folder
    #[serde(rename = "link.target.attached")]
    LinkTargetAttached {
        /// The text, as written.
        written: String,
        /// The file it points at.
        target: ContentPath,
        /// Every file it could mean, in path order.
        candidates: Vec<ContentPath>,
    },
    /// `format.obsidian.chosen`: the folder holds `.obsidian/`, so its markdown is read as Obsidian's
    #[serde(rename = "format.obsidian.chosen")]
    FormatObsidianChosen,
    /// `format.pin.chosen`: `ink.toml` pins `site.format` to `{format}`, so the markdown is read with it
    #[serde(rename = "format.pin.chosen")]
    FormatPinChosen {
        /// The format plugin's id.
        format: String,
    },
    /// `site.home.generated`: no home page was found, so the home page lists every page
    #[serde(rename = "site.home.generated")]
    SiteHomeGenerated,
    /// `fact.date.bound`: only a bound is known for `{decision}`, not after {bound}, so it is not used
    #[serde(rename = "fact.date.bound")]
    FactDateBound {
        /// The decision code it is about.
        decision: AnyCode,
        /// The latest the date can be.
        bound: String,
    },
    /// `feed.post.undated`: the post has no date, so the feeds leave it out
    #[serde(rename = "feed.post.undated")]
    FeedPostUndated,
    /// `feed.post.none`: the site has no dated posts, so it has no feeds
    #[serde(rename = "feed.post.none")]
    FeedPostNone,
    /// `source.output.skipped`: {path} holds the build's own output, so it is not read
    #[serde(rename = "source.output.skipped")]
    SourceOutputSkipped {
        /// The file.
        path: ContentPath,
    },
    /// `file.ignore.inferred`: {path} is hidden, another tool's or about the repository, so it is not part of the site
    #[serde(rename = "file.ignore.inferred")]
    FileIgnoreInferred {
        /// The file.
        path: ContentPath,
    },
    /// `source.cache.skipped`: {path} is the cache ink keeps between builds, so it is not read
    #[serde(rename = "source.cache.skipped")]
    SourceCacheSkipped {
        /// The file.
        path: ContentPath,
    },
    /// `source.link.skipped`: {path} links to a folder of the site, which is read at its own path, so the link is not followed
    #[serde(rename = "source.link.skipped")]
    SourceLinkSkipped {
        /// The file.
        path: ContentPath,
    },
    /// `source.git.chosen`: the folder is a git repository, so the site is read from its commit {commit}, not from the files on disk
    #[serde(rename = "source.git.chosen")]
    SourceGitChosen {
        /// The commit, as git writes its id.
        commit: String,
    },
    /// `source.history.absent`: the source has no history, so `{decision}` is not taken from it
    #[serde(rename = "source.history.absent")]
    SourceHistoryAbsent {
        /// The decision code it is about.
        decision: AnyCode,
    },
    /// `source.history.shallow`: the history stops at commit {commit}, a shallow clone's boundary, so `{decision}` of a file not changed since is only a bound, not after {bound}
    #[serde(rename = "source.history.shallow")]
    SourceHistoryShallow {
        /// The decision code it is about.
        decision: AnyCode,
        /// The commit, as git writes its id.
        commit: String,
        /// The latest the date can be.
        bound: String,
    },
    /// `source.history.moved`: {count} files came to their path by a move, and the history does not follow renames, so their `{decision}` is when they moved
    #[serde(rename = "source.history.moved")]
    SourceHistoryMoved {
        /// The decision code it is about.
        decision: AnyCode,
        /// How many there are.
        count: u64,
    },
    /// `source.submodule.skipped`: {path} is a git submodule, whose files live in another repository, so it is not read
    #[serde(rename = "source.submodule.skipped")]
    SourceSubmoduleSkipped {
        /// The file.
        path: ContentPath,
    },
    /// `source.lfs.pointer`: {path} is a Git LFS pointer, so the site holds the pointer's text, not the file it stands for
    #[serde(rename = "source.lfs.pointer")]
    SourceLfsPointer {
        /// The file.
        path: ContentPath,
    },
    /// `build.record.unread`: the previous build's decision record could not be read, so nothing is compared with it: {reason}
    #[serde(rename = "build.record.unread")]
    BuildRecordUnread {
        /// Why, as the part that refused it says.
        reason: String,
    },
    /// `build.address.default`: no address was given, so feeds, the sitemap and canonical links use {address}
    #[serde(rename = "build.address.default")]
    BuildAddressDefault {
        /// The address used, as written.
        address: String,
    },
    /// `code.language.unknown`: no grammar knows the language `{language}`, so its code is shown without highlighting
    #[serde(rename = "code.language.unknown")]
    CodeLanguageUnknown {
        /// The language, as written after the opening fence.
        language: String,
    },
    /// `image.animation.kept`: {path} is animated, so it is served as it is, with no smaller copies
    #[serde(rename = "image.animation.kept")]
    ImageAnimationKept {
        /// The file.
        path: ContentPath,
    },
    /// `image.format.kept`: {path} is served as it is, metadata included: uses.ink makes no smaller copies of AVIF images
    #[serde(rename = "image.format.kept")]
    ImageFormatKept {
        /// The file.
        path: ContentPath,
    },
    /// `render.cache.cold`: {folder} held no cache, so everything this build makes is made from scratch
    #[serde(rename = "render.cache.cold")]
    RenderCacheCold {
        /// The folder on disk, as the system names it.
        folder: String,
    },
    /// `render.cache.used`: {reused} pages were taken from the cache and {rendered} rendered
    #[serde(rename = "render.cache.used")]
    RenderCacheUsed {
        /// How many were taken from the cache.
        reused: u64,
        /// How many were made again.
        rendered: u64,
    },
    /// `render.cache.unkeyed`: the theme {theme} does not say what its pages are made from, so every page is rendered again by every build
    #[serde(rename = "render.cache.unkeyed")]
    RenderCacheUnkeyed {
        /// The theme's name.
        theme: String,
    },
    /// `cache.folder.unusable`: {folder} cannot hold the cache, so nothing is kept between builds
    #[serde(rename = "cache.folder.unusable")]
    CacheFolderUnusable {
        /// The folder on disk, as the system names it.
        folder: String,
    },
    /// `cache.entry.corrupt`: the cache entry {entry} does not match its hash, so it is made again
    #[serde(rename = "cache.entry.corrupt")]
    CacheEntryCorrupt {
        /// The cache entry, as its kind and digest: `image/<hash>`.
        entry: String,
    },
    /// `cache.entry.unwritten`: the cache entry {entry} could not be written, so the next build makes it again
    #[serde(rename = "cache.entry.unwritten")]
    CacheEntryUnwritten {
        /// The cache entry, as its kind and digest: `image/<hash>`.
        entry: String,
    },
    /// `cache.entry.evicted`: {count} cache entries used longest ago were removed, keeping the cache under {limit}
    #[serde(rename = "cache.entry.evicted")]
    CacheEntryEvicted {
        /// How many there are.
        count: u64,
        /// The most that is allowed.
        limit: Bytes,
    },
}
